<style scoped lang="scss" src="./icon-data.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import Icon from "../icon/icon";
import { IconShapeValues } from "../icon/icon.constants";
import { has } from "../../util/has";

@Component({
  components: { Icon }
})
export default class IconData extends Vue {
  @Prop({ type: Number, validator: has(IconShapeValues) }) shape;
  @Prop({ type: Number, default: 0 }) data;
  @Prop({ type: String, default: "" }) title;
}
</script>

<template>
  <div class="IconData">
    <div class="IconData__Left">
      <Icon :shape="shape" :size="32" :color="'#2356F6'" />
    </div>
    <div class="IconData__Right">
      <div class="IconData__Title">{{ title }}</div>
      <div class="IconData__Data">{{ data }}</div>
    </div>
  </div>
</template>
